// Auteur Scene SDK runtime — public entry (SDK.md §3-§6).
//
//   import { sr } from '../runtime/showreel.js';          // scenes (job/scenes/*.js)
//   import { sr } from '../../runtime/showreel.js';       // kits (job/kits/<kit>/kit.js)
//   sr.defineScene('custom:x', {layer, params, setup, render, cues, dispose});
//   sr.defineTransition('kit:k/name', {kind: 'canvas'|'css', render(tx, u, p)});
//   sr.defineKit('nature', {fonts: [...], sky(ctx, opts) {...}, ...});   // ctx.kit('nature').sky(...)
//
// stage.html (generated by showreel_core/film/page.py) calls boot({film, manifest, modules}).
// The renderer drives window.__sr: ready, dur, fps, w, h, seek(t), cues, qa(t), errors, shots().
import { Runtime } from './core/runtime.js';
import { ease, bezier } from './core/ease.js';
import * as motion from './core/motion.js';
import { makeRng, mixSeed, mulberry32 } from './core/rand.js';
import { makeNoise } from './core/noise.js';

const runtime = new Runtime();

/** The registration API shared by kits and scenes. */
export const sr = {
  version: 1,
  defineScene: (id, def) => runtime.defineScene(id, def),
  defineTransition: (id, def) => runtime.defineTransition(id, def),
  defineKit: (name, blocks) => runtime.defineKit(name, blocks),
  /** Another kit's blocks at module level (kits building on kits); ctx.kit(name) inside scenes. */
  kit: (name) => runtime.kit(name),
  // pure helpers for module-level code (scenes should prefer ctx.*)
  ease, bezier, ...motion, makeRng, mixSeed, mulberry32, makeNoise,
};

/** Boot the page: load film.json + manifest, import kit/scene modules, fonts, assets, set up shots.
 * stage.html?player adds an interactive control bar; stage.html?t=3.2 shows one frame (dev viewing only). */
export function boot(opts) {
  runtime.boot(opts);
  const q = new URLSearchParams(typeof location !== 'undefined' ? location.search : '');
  if (q.has('player')) {
    runtime.ready.then(() => import('./player.js')).then((m) => m.attachPlayer(runtime.api)).catch(() => {});
  } else if (q.has('t')) {
    runtime.ready.then(() => runtime.seek(Number(q.get('t')) || 0)).catch(() => {});
  }
  return runtime.ready;
}

if (typeof window !== 'undefined') window.__sr = runtime.api;
export default sr;
